  for (const a of pids) {
    const href = a.href;
    if (!seen.has(href)) {
      seen.add(href);
      // find container
      let container = a;
      while (container && container.parentElement && !container.innerText.includes('$')) {
        container = container.parentElement;
      }
      if (container && container.parentElement) {
        container = container.parentElement;
      }
      uniquePids.push({
