const tabId = 343605414;
const listingsDetailed = await browserjs(tabId, () => {
  // Let's inspect the cards
  // Let's find all cards that represent individual listings
  const links = Array.from(document.querySelectorAll('a[href*="/pid/"]'));
  const results = [];
  const seenUrls = new Set();

  for (const a of links) {
    if (seenUrls.has(a.href)) continue;
    // Find the smallest container that has price info
    let curr = a;
    let card = null;
    while (curr && curr !== document.body) {
      // If curr has only one /pid/ link (or is the card wrapper)
      const pidsInside = curr.querySelectorAll('a[href*="/pid/"]');
      if (pidsInside.length === 1 || curr.getAttribute('data-qa-listing') || curr.className.includes('listing') || curr.className.includes('Card')) {
        card = curr;
      }
      if (pidsInside.length > 2) {
        break;
      }
      curr = curr.parentElement;
    }

    seenUrls.add(a.href);
    results.push({
      href: a.href,
      cardText: card ? card.innerText : a.innerText
    });
  }
  return results;
});

console.log("Detailed listings:", JSON.stringify(listingsDetailed, null, 2));

